[
  {
    "createSurface": {
      "version": "v0.9",
      "surfaceId": "vlookup-fix-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json",
      "theme": {
        "primaryColor": "#217346"
      }
    }
  },
  {
    "updateComponents": {
      "version": "v0.9",
      "surfaceId": "vlookup-fix-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header",
            "summary",
            "divider1",
            "context_header",
            "context_body",
            "divider2",
            "formula_header",
            "formula_intro",
            "formula_list",
            "divider3",
            "formatting_header",
            "formatting_intro",
            "formatting_list",
            "divider4",
            "table_header",
            "table_list",
            "divider5",
            "actions_header",
            "actions_row"
          ]
        },
        {
          "id": "header",
          "component": "Text",
          "variant": "h2",
          "text": "VLOOKUP Text-Number Mismatch Fix"
        },
        {
          "id": "summary",
          "component": "Text",
          "variant": "body",
          "text": "VLOOKUP fails with #N/A when the lookup value is text but the source table has numbers due to data type mismatch; fix it by either converting the lookup value to a number in the formula or standardizing the source table formats."
        },
        {
          "id": "divider1",
          "component": "Divider"
        },
        {
          "id": "context_header",
          "component": "Text",
          "variant": "h3",
          "text": "Excel Data Setup Context"
        },
        {
          "id": "context_body",
          "component": "Text",
          "variant": "body",
          "text": "This guide assumes the lookup value (e.g., in cell A2) appears as a number but is text (green triangle indicator), while the source table's first column (e.g., B:B in another sheet) holds true numbers. Exact ranges like =VLOOKUP(A2, Sheet2!B:C, 2, FALSE) are used in examples."
        },
        {
          "id": "divider2",
          "component": "Divider"
        },
        {
          "id": "formula_header",
          "component": "Text",
          "variant": "h3",
          "text": "Formula-Based Fixes"
        },
        {
          "id": "formula_intro",
          "component": "Text",
          "variant": "body",
          "text": "Use these modified VLOOKUP formulas to handle the text lookup value without changing source data:"
        },
        {
          "id": "formula_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "fix_value",
            "fix_arithmetic",
            "fix_text",
            "fix_test"
          ]
        },
        {
          "id": "fix_value",
          "component": "Card",
          "child": "fix_value_col"
        },
        {
          "id": "fix_value_col",
          "component": "Column",
          "children": [
            "fix_value_title",
            "fix_value_body"
          ]
        },
        {
          "id": "fix_value_title",
          "component": "Text",
          "variant": "h4",
          "text": "Text to Number Conversion (Primary Fix)"
        },
        {
          "id": "fix_value_body",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(VALUE(A2), Sheet2!B:C, 2, FALSE)\nThe VALUE function converts text \"4399\" to number 4399 for matching."
        },
        {
          "id": "fix_arithmetic",
          "component": "Card",
          "child": "fix_arithmetic_col"
        },
        {
          "id": "fix_arithmetic_col",
          "component": "Column",
          "children": [
            "fix_arithmetic_title",
            "fix_arithmetic_body"
          ]
        },
        {
          "id": "fix_arithmetic_title",
          "component": "Text",
          "variant": "h4",
          "text": "Quick Arithmetic Trick"
        },
        {
          "id": "fix_arithmetic_body",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(A2+0, Sheet2!B:C, 2, FALSE)\nAdding zero forces text-to-number conversion inline."
        },
        {
          "id": "fix_text",
          "component": "Card",
          "child": "fix_text_col"
        },
        {
          "id": "fix_text_col",
          "component": "Column",
          "children": [
            "fix_text_title",
            "fix_text_body"
          ]
        },
        {
          "id": "fix_text_title",
          "component": "Text",
          "variant": "h4",
          "text": "Number to Text Conversion (Reverse Scenario)"
        },
        {
          "id": "fix_text_body",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(TEXT(A2, \"0\"), Sheet2!B:C, 2, FALSE)\nTEXT ensures number lookup matches text source."
        },
        {
          "id": "fix_test",
          "component": "Card",
          "child": "fix_test_col"
        },
        {
          "id": "fix_test_col",
          "component": "Column",
          "children": [
            "fix_test_title",
            "fix_test_body"
          ]
        },
        {
          "id": "fix_test_title",
          "component": "Text",
          "variant": "h4",
          "text": "Test Data Types First"
        },
        {
          "id": "fix_test_body",
          "component": "Text",
          "variant": "body",
          "text": "=ISTEXT(A2) returns TRUE if lookup is text; =ISNUMBER(B9) checks source cell."
        },
        {
          "id": "divider3",
          "component": "Divider"
        },
        {
          "id": "formatting_header",
          "component": "Text",
          "variant": "h3",
          "text": "Formatting-Based Fixes"
        },
        {
          "id": "formatting_intro",
          "component": "Text",
          "variant": "body",
          "text": "Standardize source table or lookup column permanently:"
        },
        {
          "id": "formatting_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "fmt_source",
            "fmt_lookup",
            "fmt_verify"
          ]
        },
        {
          "id": "fmt_source",
          "component": "Column",
          "children": [
            "fmt_source_title",
            "fmt_source_body"
          ]
        },
        {
          "id": "fmt_source_title",
          "component": "Text",
          "variant": "h4",
          "text": "Convert Source Text to Numbers (If Needed)"
        },
        {
          "id": "fmt_source_body",
          "component": "Text",
          "variant": "body",
          "text": "1. Select source column (e.g., Sheet2!B:B).\n2. Click green error triangle > Convert to Number.\nOr use Paste Special: Copy empty cell, select range, right-click > Paste Special > Add."
        },
        {
          "id": "fmt_lookup",
          "component": "Column",
          "children": [
            "fmt_lookup_title",
            "fmt_lookup_body"
          ]
        },
        {
          "id": "fmt_lookup_title",
          "component": "Text",
          "variant": "h4",
          "text": "Convert Lookup Text to Numbers"
        },
        {
          "id": "fmt_lookup_body",
          "component": "Text",
          "variant": "body",
          "text": "1. Select lookup cells (e.g., A:A).\n2. Data tab > Text to Columns > Finish (triggers conversion).\nOr multiply by 1: Enter 1 in helper cell, copy, Paste Special > Multiply."
        },
        {
          "id": "fmt_verify",
          "component": "Column",
          "children": [
            "fmt_verify_title",
            "fmt_verify_body"
          ]
        },
        {
          "id": "fmt_verify_title",
          "component": "Text",
          "variant": "h4",
          "text": "Verify Post-Fix"
        },
        {
          "id": "fmt_verify_body",
          "component": "Text",
          "variant": "body",
          "text": "Recalculate with F9; green triangles disappear for true numbers."
        },
        {
          "id": "divider4",
          "component": "Divider"
        },
        {
          "id": "table_header",
          "component": "Text",
          "variant": "h3",
          "text": "VLOOKUP Troubleshooting Table"
        },
        {
          "id": "table_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "table_row_head",
            "table_row_1",
            "table_row_2",
            "table_row_3"
          ]
        },
        {
          "id": "table_row_head",
          "component": "Row",
          "children": [
            "th_1",
            "th_2",
            "th_3",
            "th_4"
          ]
        },
        {
          "id": "th_1",
          "component": "Text",
          "variant": "h5",
          "text": "Issue Indicator",
          "weight": 1
        },
        {
          "id": "th_2",
          "component": "Text",
          "variant": "h5",
          "text": "Test Formula",
          "weight": 1
        },
        {
          "id": "th_3",
          "component": "Text",
          "variant": "h5",
          "text": "Formula Fix",
          "weight": 1
        },
        {
          "id": "th_4",
          "component": "Text",
          "variant": "h5",
          "text": "Formatting Fix",
          "weight": 1
        },
        {
          "id": "table_row_1",
          "component": "Row",
          "children": [
            "td_1_1",
            "td_1_2",
            "td_1_3",
            "td_1_4"
          ]
        },
        {
          "id": "td_1_1",
          "component": "Text",
          "variant": "body",
          "text": "Green triangle on lookup",
          "weight": 1
        },
        {
          "id": "td_1_2",
          "component": "Text",
          "variant": "body",
          "text": "=ISTEXT(A2)",
          "weight": 1
        },
        {
          "id": "td_1_3",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(VALUE(A2), table, col, FALSE)",
          "weight": 1
        },
        {
          "id": "td_1_4",
          "component": "Text",
          "variant": "body",
          "text": "Text to Columns > Finish",
          "weight": 1
        },
        {
          "id": "table_row_2",
          "component": "Row",
          "children": [
            "td_2_1",
            "td_2_2",
            "td_2_3",
            "td_2_4"
          ]
        },
        {
          "id": "td_2_1",
          "component": "Text",
          "variant": "body",
          "text": "#N/A despite visual match",
          "weight": 1
        },
        {
          "id": "td_2_2",
          "component": "Text",
          "variant": "body",
          "text": "=ISNUMBER(B9)",
          "weight": 1
        },
        {
          "id": "td_2_3",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(A2+0, table, col, FALSE)",
          "weight": 1
        },
        {
          "id": "td_2_4",
          "component": "Text",
          "variant": "body",
          "text": "Error icon > Convert to Number",
          "weight": 1
        },
        {
          "id": "table_row_3",
          "component": "Row",
          "children": [
            "td_3_1",
            "td_3_2",
            "td_3_3",
            "td_3_4"
          ]
        },
        {
          "id": "td_3_1",
          "component": "Text",
          "variant": "body",
          "text": "Extra spaces suspected",
          "weight": 1
        },
        {
          "id": "td_3_2",
          "component": "Text",
          "variant": "body",
          "text": "=LEN(TRIM(A2)) vs =LEN(A2)",
          "weight": 1
        },
        {
          "id": "td_3_3",
          "component": "Text",
          "variant": "body",
          "text": "=VLOOKUP(TRIM(VALUE(A2)), table, col, FALSE)",
          "weight": 1
        },
        {
          "id": "td_3_4",
          "component": "Text",
          "variant": "body",
          "text": "=TRIM in helper column",
          "weight": 1
        },
        {
          "id": "divider5",
          "component": "Divider"
        },
        {
          "id": "actions_header",
          "component": "Text",
          "variant": "h3",
          "text": "Quick Actions"
        },
        {
          "id": "actions_row",
          "component": "Row",
          "justify": "start",
          "children": [
            "btn_ms_guide",
            "btn_error_check",
            "btn_video"
          ]
        },
        {
          "id": "btn_ms_guide",
          "component": "Button",
          "variant": "borderless",
          "child": "txt_ms_guide",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://support.microsoft.com/en-us/office/vlookup-function-0bbc8083-26fe-4963-8ab8-93a18ad188a1"
              }
            }
          }
        },
        {
          "id": "txt_ms_guide",
          "component": "Text",
          "text": "Official Microsoft VLOOKUP Guide"
        },
        {
          "id": "btn_error_check",
          "component": "Button",
          "variant": "borderless",
          "child": "txt_error_check",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://support.microsoft.com/en-us/office/convert-numbers-stored-as-text-to-numbers-in-excel-40105f2a-fe79-4477-a171-c5bad0f0a885"
              }
            }
          }
        },
        {
          "id": "txt_error_check",
          "component": "Text",
          "text": "Excel Error Checking Toggle"
        },
        {
          "id": "btn_video",
          "component": "Button",
          "variant": "borderless",
          "child": "txt_video",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.youtube.com/watch?v=rRc2IGTMRWw"
              }
            }
          }
        },
        {
          "id": "txt_video",
          "component": "Text",
          "text": "MrExcel VLOOKUP Video"
        }
      ]
    }
  }
]
